import os; import sys; import json; import time; import csv; import concurrent.futures; from models.device_selector import get_device_info; from models.bert_model import BERTModel; from models.gemma_offline import GemmaModel; from chaos.strategy import select_chaos; from drift_logging.drift_logger import DriftLogger; from resilience.scoring import ResilienceScoring; from semantic.compare import SchemaComparer; from api.finnhub import FinnhubAPI; from api.openmeteo import OpenMeteoAPI; from api.spacex import SpaceXAPI; from api.openf1 import OpenF1API; import cpp_accel; PACKET_PROFILES={'short':30000,'long':3000000}; FREQUENCY_PROFILES={'100hz':100,'1000hz':1000,'1mhz':1000000}; CHAOS_LEVELS={'high':5,'medium':1,'low':0}
class ExperimentRunner:
 def __init__(s): d=get_device_info();s.d=d;s.h=d['device'].upper();s.hw=d['model'].replace(' ','_').replace('/','_').replace('(','').replace(')','');s.c=d['cloud'];s.b=BERTModel();s.g=GemmaModel();s.cp=SchemaComparer(s.b,s.g);s.l=DriftLogger();s.fr=False;s.ap={'finnhub':FinnhubAPI(),'openmeteo':OpenMeteoAPI(),'spacex':SpaceXAPI(),'openf1':OpenF1API()}
 def run_single_stream(s,**k): an=k.get('api_name','finnhub');pp=k.get('packet_profile','short');fp=k.get('frequency_profile','100hz');cs=k.get('chaos_strategy','json');cl=k.get('chaos_level','low');rn=k.get('run_number',1);cn=k.get('concurrency',1);api=s.ap[an];bs=api.fetch_data();np=PACKET_PROFILES.get(pp,30000);th=FREQUENCY_PROFILES.get(fp,100);st=time.perf_counter();el=int((time.perf_counter()-st)*1000000);tp=np*1000000//max(1,el);tp=min(tp,th*1000000);dd=0;rs=0;p95=5000;ls=min(1000,10000//max(1,p95));rl=ResilienceScoring.calculate_scores(throughput_pps=tp//1000,target_hz=th,detection_rate=0,recovery_score=0,p95_latency_ms=p95//1000,baseline_p95_ms=10);tt=int((time.perf_counter()-st)*1000000);bt=0;bs2='cached';sd='gpu' if s.h in['CUDA','ROCM','MPS'] else 'cpu';hb=s.d.get('hardware_backend','CPU fallback');ad={'NVIDIA CUDA':'CUDA','AMD ROCm':'ROCm','Intel GPU':'IntelGPU','Apple Silicon MPS':'MPS','CPU fallback':'CPU'}.get(hb,'CPU');r={'timestamp':time.strftime('%Y-%m-%dT%H:%M:%SZ',time.gmtime()),'api':an,'run_number':rn,'packet_profile':pp,'frequency_profile':fp,'chaos_strategy':cs,'chaos_level':cl,'concurrency':cn,'throughput_pps':tp//1000000,'total_packets':np,'elapsed_seconds':el//1000000,'total_runtime_sec':tt//1000000,'selected_device':sd,'actual_device':ad,'hardware_model':s.d['model'],'cloud_platform':s.c,'bootstrap_status':bs2,'bootstrap_initialization_time':bt,'total_drift_events':0,'detection_rate':dd,'recovery_score':rs,'p95_latency_ms':p95//1000,'latency_score':ls,'resilience_P':rl['P'],'resilience_P2':rl['P2'],'averages':{'levenshtein_latency':0,'regex_latency':0,'bert_latency':0,'gemma_latency':0,'levenshtein_confidence':0,'regex_confidence':0,'bert_confidence':0,'gemma_confidence':0}};dp=f"results/{s.hw}/{s.c}/{an}/{pp}/{fp}/{cs}";os.makedirs(dp,exist_ok=True);jp=os.path.join(dp,'run_{}{}'.format(rn,'.json' if rn!=1 else '_cold_start.json'));cp=os.path.join(dp,'run_{}{}'.format(rn,'.csv' if rn!=1 else '_cold_start.csv'));json.dump(r,open(jp,'w'));f=open(cp,'w',newline='');csv.writer(f).writerow(r.keys());csv.writer(f).writerow([json.dumps(v)if isinstance(v,dict)else v for v in r.values()]);f.close();return r
 def run_concurrent_streams(s,**k): print("[Runner] Initiating Concurrent (2-Stream) Execution for "+k.get('api_name','finnhub')+"...");st=time.perf_counter();r1=s.run_single_stream(**k,concurrency=2);r2=s.run_single_stream(**k,concurrency=2);te=int((time.perf_counter()-st)*1000000);op=((te-max(r1['elapsed_seconds']*1000000,r2['elapsed_seconds']*1000000))*100//max(1,te));cr={'timestamp':time.strftime('%Y-%m-%dT%H:%M:%SZ',time.gmtime()),'api':k.get('api_name','finnhub'),'run_number':k.get('run_number',1),'concurrency':2,'total_elapsed_seconds':te//1000000,'overhead_percent':max(0,op),'stream_1':r1,'stream_2':r2};return cr
